#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
enum NumpyDType {
    UInt8,
    Int8,
    Float16,
    UInt16,
    Int16,
    Float32,
    UInt32,
    Int32,
    Complex64,
    UInt64,
    Int64,
    Float64,
    Complex128,
}

impl NumpyDType {
    /// Returns the bit size of the dtype.
    fn dtype_size(&self) -> u32 {
        use NumpyDType::*;
        match self {
            UInt8 | Int8 => 8,
            Float16 | UInt16 | Int16 => 16,
            Float32 | UInt32 | Int32 | Complex64 => 32,
            Float64 | UInt64 | Int64 | Complex128 => 64,
        }
    }

    /// Returns the kind order as described:
    /// unsigned int = 0, signed int = 1, floating-point = 2, complex = 3.
    fn dtype_kind_order(&self) -> u32 {
        use NumpyDType::*;
        match self {
            UInt8 | UInt16 | UInt32 | UInt64 => 0,
            Int8 | Int16 | Int32 | Int64 => 1,
            Float16 | Float32 | Float64 => 2,
            Complex64 | Complex128 => 3,
        }
    }

    /// Returns whether this dtype can represent the given value.
    /// For floats and complex types: always true.
    fn can_represent_value(&self, value: i8) -> bool {
        use NumpyDType::*;
        match self {
            // unsigned ints represent [0..2^{bits}-1]
            UInt8 => value >= 0 && (value as u8) <= u8::MAX,
            UInt16 => value >= 0,
            UInt32 => value >= 0,
            UInt64 => value >= 0,
            // signed ints represent [-2^{bits-1} .. 2^{bits-1} - 1]
            Int8 => true, // all i8 values fit in Int8 by definition
            Int16 => true, // any i8 fits in Int16 (since Int16 wider)
            Int32 => true,
            Int64 => true,
            // floating-point and complex always true
            Float16 | Float32 | Float64 | Complex64 | Complex128 => true,
        }
    }
}

/// Given an i8 value, returns the minimal NumpyDType that
/// - can represent the value,
/// - no smaller bit-size type can represent the value,
/// - and among same bit-size types that can represent the value,
///   has minimal dtype_kind_order.
fn min_scalar_type(value: i8) -> NumpyDType {
    use NumpyDType::*;

    // Group types by size ascending, and within each size sorted increasing by kind_order
    // (this ordering respects the preference for kind_order on tie)
    let candidates = [
        // 8-bit types sorted by kind order: UInt8(0), Int8(1), Float16(2)
        UInt8, Int8, Float16,
        // 16-bit: UInt16(0), Int16(1), Float32(2)
        UInt16, Int16, Float32,
        // 32-bit: UInt32(0), Int32(1), Complex64(3)
        UInt32, Int32, Complex64,
        // 64-bit: UInt64(0), Int64(1), Float64(2), Complex128(3)
        UInt64, Int64, Float64, Complex128,
    ];

    // Iterate over candidates by ascending size and preferred kind order
    // Return the first candidate dtype that can represent the value
    for &dtype in candidates.iter() {
        if dtype.can_represent_value(value) {
            return dtype;
        }
    }

    // Should never reach here because Float64/Complex128 always represent any value
    // But to satisfy return type, fallback to Int64 (largest signed int)
    Int64
}